{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Progesterone, a steroid sharing the enone A-ring and lipophilic core, has approximately 5% oral bioavailability in humans due to extensive gut and liver metabolism; its high transfer score makes this a strong anchor for low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Testosterone, a steroid with enone and hydroxyl functionality, has absolute oral bioavailability of 3.6 ± 2.5% in humans due to first-pass metabolism; the high transfer score supports low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Loteprednol etabonate, a corticosteroid ester with enone and C21 ester, showed very low oral bioavailability in healthy volunteers after a 40-mg oral dose; moderate-high transfer supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C66"],
      "claim": "Mometasone, a corticosteroid with enone and halogen substitution, has <1% oral bioavailability in humans; moderate transfer supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "High oral bioavailability values for hydrocortisone, dexamethasone, and methylprednisolone are contradictory in direction, but their transfer scores are very low because they lack the acetal/ester and high first-pass liability of the query; they do not outweigh the high-transfer low-F evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is budesonide, a corticosteroid acetal/ester with extensive first-pass metabolism. The highest-transfer analogues—progesterone, testosterone, loteprednol, and mometasone—all show low oral bioavailability in humans, strongly supporting F < 20%. High-F corticosteroids have very low transfer scores and are outweighed.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for budesonide is provided in the evidence set.",
    "Budesonide-specific metabolic pathways, such as acetal cleavage and ester hydrolysis, are not directly represented by any single analogue.",
    "Some records appear mismatched to their listed structures (e.g., NOMAC, cyclosporine) and were not used as primary evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

